require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/ui.php';$admin=requireAdmin();if(empty($_SESSION['tracking_delete_csrf']))$_SESSION['tracking_delete_csrf']=bin2hex(random_bytes(32));ensureShiftPhotoSchema();$active=db()->query("SELECT s.*,u.nama_lengkap,u.nomor_pegawai,u.role FROM tracking_sessions s JOIN users u ON u.id=s.user_id WHERE s.status='active' ORDER BY s.last_seen_at DESC")->fetchAll();$history=db()->query("SELECT s.*,u.nama_lengkap,u.nomor_pegawai,u.role,(SELECT COUNT(*) FROM tracking_points p WHERE p.session_id=s.id) point_count,(SELECT COUNT(*) FROM laporan l WHERE l.report_session_id=s.id) report_photos FROM tracking_sessions s JOIN users u ON u.id=s.user_id ORDER BY s.id DESC LIMIT 50")->fetchAll();$meUser=array('nama_lengkap'=>$admin['nama_lengkap']??'Pengelola Layanan Cikoko','role'=>'admin');ui_begin('Pemantauan Jam Kerja','tracking',$meUser,true);ui_page_title('Pemantauan Jam Kerja Pegawai','Pantau PJLP / PPSU dan PPPK Paruh Waktu yang telah memulai sesi kerja, posisi terakhir, dan riwayat sesi kerja.','Dasbor Administrasi › Pemantauan Jam Kerja');
?>
<div class="stats-grid"><div class="stat-card"><div class="stat-icon green"><?=ui_icon('track')?></div><div><small>Petugas Sedang Bertugas</small><div class="stat-number" id="activeCount"><?=count($active)?></div><small>sesi kerja aktif</small></div></div><div class="stat-card"><div class="stat-icon blue"><?=ui_icon('clock')?></div><div><small>Riwayat Ditampilkan</small><div class="stat-number"><?=count($history)?></div><small>50 sesi terakhir</small></div></div></div>
<div class="tracking-grid"><div class="card"><div class="card-header"><div class="card-title"><?=ui_icon('pin')?> Peta Posisi Terakhir</div><small class="muted">Informasi diperbarui secara otomatis sekitar setiap 5 detik</small></div><div class="map-live" id="adminMap"></div><div class="notice info" style="margin-top:12px">Status <b>Terkini</b> menunjukkan posisi diperbarui dalam 15 detik terakhir. <b>Perlu Pembaruan</b> menunjukkan pembaruan terakhir antara 16 hingga 90 detik. Lebih dari 90 detik ditandai tidak terkini. Data ini merupakan posisi terakhir yang dikirim perangkat petugas saat sesi kerja aktif.</div></div>
<div class="card"><div class="card-header"><div class="card-title"><?=ui_icon('users')?> Petugas Aktif</div><small class="muted" id="serverTime"><?=date('d-m-Y H:i:s')?> WIB</small></div><div id="trackingList" class="tracking-list"><?php foreach($active as $r):$f='offline';?><div class="tracking-item"><div class="meta"><strong><?=h($r['nama_lengkap'])?></strong><small><?=h(roleLabel((string)$r['role']))?> · <?=h($r['nomor_pegawai']?:'-')?> · Pembaruan <?=h($r['last_seen_at'])?></small><small>Koordinat <?=h($r['last_lat'])?>, <?=h($r['last_lng'])?> · ±<?=h((string)round((float)$r['last_accuracy']))?> m</small></div><div><span class="status-<?=h($f)?>"><?=h(array('live'=>'Terkini','stale'=>'Perlu Pembaruan','offline'=>'Memeriksa GPS')[$f]??'Belum Tersedia')?></span><br><a target="_blank" href="<?=h(mapsUrl($r['last_lat'],$r['last_lng']))?>">Google Maps</a></div></div><?php endforeach;?><?php if(!$active):?><div class="empty">Belum ada petugas yang sedang bertugas.</div><?php endif;?></div></div></div>
<div class="card table-card" style="margin-top:16px"><div class="card-header"><div class="card-title"><?=ui_icon('clock')?> Riwayat Sesi Kerja</div><small class="muted">Klik Detail untuk melihat rute, posisi awal/akhir, akurasi, dan dokumentasi foto.</small></div><table class="data-table"><thead><tr><th>Petugas</th><th>Mulai Bertugas</th><th>Selesai Bertugas</th><th>Status</th><th>Titik GPS</th><th>Foto Lapangan</th><th>Posisi Terakhir</th><th>Detail / Tindakan Admin</th></tr></thead><tbody><?php if(!$history):?><tr><td colspan="8" class="empty">Belum ada riwayat jam kerja.</td></tr><?php endif;?><?php foreach($history as $r):?><tr><td><b><?=h($r['nama_lengkap'])?></b><br><small class="muted"><?=h(roleLabel((string)$r['role']))?> · <?=h($r['nomor_pegawai']?:'-')?></small></td><td><?=h($r['checkin_at'])?></td><td><?=h($r['checkout_at']?:'-')?></td><td><span class="pill <?=h(statusClass($r['status']))?>"><?=h(statusLabel($r['status']))?></span></td><td><?=(int)$r['point_count']?></td><td><b><?=(int)$r['report_photos']?> foto</b></td><td><a target="_blank" rel="noopener" href="<?=h(mapsUrl($r['last_lat'],$r['last_lng']))?>">Google Maps</a></td><td><button type="button" class="btn light tracking-detail-btn" data-session-id="<?=(int)$r['id']?>">Lihat Rincian</button> <?php if($r['status']!=='active'):?><button type="button" class="btn tracking-delete-btn" style="background:#b42318;color:#fff;margin-top:5px" data-session-id="<?=(int)$r['id']?>" data-person="<?=h($r['nama_lengkap'])?>">Hapus Permanen</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<div class="modal" id="trackingDetailModal"><div class="modal-card tracking-detail-modal-card"><div class="modal-head"><div><b>Detail Sesi Jam Kerja</b><div class="muted" id="detailSubtitle" style="font-size:10px;margin-top:3px">Memuat data sesi...</div></div><button class="modal-close" type="button" data-modal-close>×</button></div><div id="trackingDetailBody"><div class="empty">Memuat detail sesi...</div></div></div></div>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
let map=null,layer=null;function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function setup(){if(typeof L==='undefined'){document.getElementById('adminMap').innerHTML='<div style="padding:24px">Peta tidak dapat dimuat. Data koordinat dan tautan Google Maps tetap tersedia.</div>';return;}map=L.map('adminMap').setView([-6.244,106.800],14);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'&copy; OpenStreetMap'}).addTo(map);layer=L.layerGroup().addTo(map);}
let detailMap=null,detailLayer=null;
function esc(s){return escapeHtml(s==null?'':s);}
function photoCard(title,url,emptyText){return '<div class="tracking-photo-card"><div class="tracking-photo-title">'+esc(title)+'</div>'+(url?'<a href="'+esc(url)+'" target="_blank" rel="noopener"><img src="'+esc(url)+'" alt="'+esc(title)+'"></a>':'<div class="tracking-photo-empty">'+esc(emptyText)+'</div>')+'</div>';}
function deviceLabel(raw){const ua=String(raw||'').trim();if(!ua)return 'Tidak diketahui';const android=ua.match(/Android\s+([0-9.]+)/i);if(android){const model=ua.match(/Android\s+[0-9.]+;\s*([^;)]+)/i);let name=model?model[1].split(/\s+Build\//i)[0].trim():'';if(/^(wv|[a-z]{2}(?:[-_][a-z]{2})?)$/i.test(name))name='';return 'Android '+android[1]+(name?' · '+name.slice(0,60):'');}if(/iPad/i.test(ua))return 'iPad';if(/iPhone/i.test(ua))return 'iPhone';if(/Windows/i.test(ua))return 'Komputer Windows';if(/Macintosh|Mac OS X/i.test(ua))return 'Komputer Mac';if(/Linux/i.test(ua))return 'Komputer Linux';return 'Perangkat lainnya';}
function renderDetail(d){
 const body=document.getElementById('trackingDetailBody');document.getElementById('detailSubtitle').textContent=d.nama_lengkap+' · '+d.role_label+' · '+(d.nomor_pegawai||'-');
 const distanceM=Number(d.distance_m||0);
 const distanceText=distanceM<1000?Math.round(distanceM)+' m':(distanceM/1000).toFixed(2)+' km';
 const routeNote='<div class="tracking-route-note"><b>Perkiraan GPS:</b> Jarak disaring berdasarkan akurasi; pergeseran kecil saat diam tidak dihitung. Garis terputus jika data tidak memadai. Lingkaran menunjukkan perkiraan ketidakpastian lokasi, bukan batas kantor. Titik di luar gedung belum membuktikan pegawai meninggalkan kantor.</div>';
 const legacyPhotoNote=(!d.checkin_photo_url&&!d.checkout_photo_url)?'<div class="tracking-photo-legacy-note"><b>Dokumentasi foto belum tersedia.</b> Riwayat ini dibuat sebelum dokumentasi foto pemantauan tersedia. Foto hanya tersedia untuk sesi baru yang memulai sesi kerja dan Selesai Bertugas setelah pembaruan V8/V9.</div>':'';
 body.innerHTML='<div class="tracking-detail-summary"><div><span>Status</span><b>'+esc(d.status_label)+'</b></div><div><span>Mulai Bertugas</span><b>'+esc(d.checkin_at)+'</b></div><div><span>Selesai Bertugas</span><b>'+esc(d.checkout_at||'-')+'</b></div><div><span>Durasi</span><b>'+esc(d.duration)+'</b></div><div><span>Titik GPS</span><b>'+esc(d.point_count)+' titik</b></div><div><span>Estimasi Jarak Tersaring</span><b>'+distanceText+'</b></div></div>'+
 '<div class="tracking-detail-layout"><div><div class="tracking-detail-section-title tracking-route-heading"><span>Rute & Posisi</span><small>Titik terakhir adalah hasil GPS perangkat. Lokasi dapat bergeser, terutama di dalam gedung.</small></div><div class="tracking-map-key"><span><i class="key-in">IN</i> Mulai Bertugas</span><span><i class="key-route"></i> Jalur Perjalanan</span><span><i class="key-point"></i> Titik GPS</span><span><i class="key-out">OUT</i> Selesai Bertugas</span></div><div id="detailMap" class="map-live tracking-detail-map"></div>'+routeNote+'<div class="tracking-location-grid"><div><span>Posisi Awal Bertugas</span><b>'+Number(d.checkin_lat).toFixed(6)+', '+Number(d.checkin_lng).toFixed(6)+'</b><small>Akurasi ±'+Math.round(Number(d.checkin_accuracy||0))+' m</small><a target="_blank" rel="noopener" href="'+esc(d.checkin_maps)+'">Buka Google Maps</a></div><div><span>Posisi Akhir Bertugas</span><b>'+(d.checkout_lat==null?'-':Number(d.checkout_lat).toFixed(6)+', '+Number(d.checkout_lng).toFixed(6))+'</b><small>'+(d.checkout_accuracy==null?'Belum tersedia':'Akurasi ±'+Math.round(Number(d.checkout_accuracy))+' m')+'</small>'+(d.checkout_maps?'<a target="_blank" rel="noopener" href="'+esc(d.checkout_maps)+'">Buka Google Maps</a>':'')+'</div></div></div><div><div class="tracking-detail-section-title">Dokumentasi Foto</div>'+legacyPhotoNote+'<div class="tracking-photo-grid">'+photoCard('Foto Mulai Bertugas',d.checkin_photo_url,'Tidak ada foto mulai bertugas yang tersimpan untuk sesi ini.')+photoCard('Foto Selesai Bertugas',d.checkout_photo_url,'Tidak ada foto selesai bertugas yang tersimpan untuk sesi ini.')+'</div><div class="detail-item" style="margin-top:12px"><small>Perangkat Pengguna</small><b style="font-size:12px;line-height:1.5;overflow-wrap:anywhere">'+esc(deviceLabel(d.device_info))+'</b><small style="display:block;margin-top:8px">No. HP Pengguna</small><b style="font-size:12px;line-height:1.5;overflow-wrap:anywhere">'+esc(d.no_hp||'Belum diisi')+'</b></div></div></div>';
 setTimeout(()=>{
  if(typeof L==='undefined')return;
  const el=document.getElementById('detailMap');if(!el)return;
  if(detailMap){detailMap.remove();detailMap=null;}
  detailMap=L.map(el,{zoomControl:true}).setView([d.checkin_lat,d.checkin_lng],16);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'&copy; OpenStreetMap'}).addTo(detailMap);
  const raw=(d.points||[]).map((p,i)=>({lat:parseFloat(p.latitude),lng:parseFloat(p.longitude),accuracy:parseFloat(p.accuracy||0),time:p.recorded_at||'',index:i+1})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lng));
  const pts=raw.map(p=>[p.lat,p.lng]);
  const pinIcon=(type,label)=>L.divIcon({className:'tracking-route-pin-host',html:'<div class="tracking-route-pin '+type+'"><span>'+label+'</span></div>',iconSize:[42,42],iconAnchor:[21,38],popupAnchor:[0,-35]});
  if(pts.length){
    (d.route_segments||[]).forEach(segment=>{
      const line=segment.map(p=>[Number(p.latitude),Number(p.longitude)]);
      if(line.length>1){
        L.polyline(line,{weight:7,opacity:.85,color:'#ffffff',interactive:false}).addTo(detailMap);
        L.polyline(line,{weight:4,opacity:.9,color:'#1677ff'}).bindPopup('Estimasi lintasan GPS tersaring').addTo(detailMap);
      }
    });
    const sampleStep=Math.max(1,Math.ceil(raw.length/18));
    raw.forEach((p,i)=>{
      if(i===0||i===raw.length-1||i%sampleStep!==0)return;
      L.circleMarker([p.lat,p.lng],{radius:4,weight:2,color:'#ffffff',fillColor:'#1677ff',fillOpacity:1}).bindPopup('<b>Titik GPS '+p.index+'</b><br>'+esc(p.time||'-')+'<br>Akurasi ±'+Math.round(p.accuracy||0)+' m').addTo(detailMap);
    });
    const first=raw[0],last=raw[raw.length-1];
    if(last.accuracy>0)L.circle([last.lat,last.lng],{radius:last.accuracy,color:last.accuracy>30?'#b45309':'#1677ff',weight:2,fillOpacity:.12}).bindPopup('Perkiraan akurasi ±'+Math.round(last.accuracy)+' m. Bukan posisi pasti.').addTo(detailMap);
    L.marker([first.lat,first.lng],{icon:pinIcon('in','IN'),zIndexOffset:1000}).bindPopup('<b>CHECK-IN</b><br>'+esc(d.checkin_at)+'<br>'+first.lat.toFixed(6)+', '+first.lng.toFixed(6)).addTo(detailMap);
    const endLabel=d.status==='closed'?'OUT':'GPS';
    L.marker([last.lat,last.lng],{icon:pinIcon(d.status==='closed'?'out':'now',endLabel),zIndexOffset:1100}).bindPopup('<b>'+(d.status==='closed'?'CHECK-OUT':'POSISI TERAKHIR')+'</b><br>'+esc(d.status==='closed'?(d.checkout_at||last.time):(last.time||d.last_seen_at))+'<br>'+last.lat.toFixed(6)+', '+last.lng.toFixed(6)+'<br>Perkiraan akurasi '+(last.accuracy>0?'±'+Math.round(last.accuracy)+' m':'tidak tersedia')).addTo(detailMap);
    if(pts.length>1)detailMap.fitBounds(pts,{padding:[45,45],maxZoom:17});else detailMap.setView(pts[0],18);
  }else{
    const ci=[Number(d.checkin_lat),Number(d.checkin_lng)];
    if(Number.isFinite(ci[0])&&Number.isFinite(ci[1]))L.marker(ci,{icon:pinIcon('in','IN')}).addTo(detailMap);
  }
  detailMap.invalidateSize();
 },100);
}
async function openDetail(id){const modal=document.getElementById('trackingDetailModal'),body=document.getElementById('trackingDetailBody');body.innerHTML='<div class="empty">Memuat detail sesi...</div>';document.getElementById('detailSubtitle').textContent='Memuat data sesi...';modal.classList.add('show');try{const r=await fetch('tracking_detail.php?id='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Detail sesi tidak dapat dimuat.');renderDetail(j.session);}catch(e){body.innerHTML='<div class="notice bad">'+esc(e.message||'Detail sesi tidak dapat dimuat.')+'</div>';}}
document.addEventListener('click',e=>{const b=e.target.closest('.tracking-detail-btn');if(b)openDetail(b.dataset.sessionId);});
const trackingDeleteCsrf=<?=json_encode($_SESSION['tracking_delete_csrf'])?>;
let trackingDeleteBusy=false;
document.addEventListener('click',async e=>{
 const btn=e.target.closest('.tracking-delete-btn');if(!btn||trackingDeleteBusy)return;
 const id=btn.dataset.sessionId,who=btn.dataset.person;
 if(!confirm('HAPUS PERMANEN riwayat sesi kerja '+who+' (ID '+id+')?\n\nTitik GPS dan data teknis tracking sesi ini akan dihapus dan tidak dapat dikembalikan. Laporan foto pegawai tidak dihapus.'))return;
 trackingDeleteBusy=true;btn.disabled=true;btn.textContent='Menghapus...';
 try{const r=await fetch('tracking_delete.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({session_id:id,csrf:trackingDeleteCsrf})});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.message||'Penghapusan gagal.');location.reload();}
 catch(err){alert(err.message||'Penghapusan gagal.');btn.disabled=false;btn.textContent='Hapus Permanen';}finally{trackingDeleteBusy=false;}
});
setup();
</script>
<script src="../assets/tracking-realtime-v9.js?v=20261015-23"></script>
<?php ui_end();?>
